// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "heat-3d.hpp"

using num_t = DATA_TYPE;

namespace {

// -----------------------------------------------------------------------------
// Layout tuning and tiling parameters
// -----------------------------------------------------------------------------

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

// Tunable spatial tile sizes for better cache locality.
// These control blocking in the i and j dimensions of the 3D grid.
constexpr std::size_t TILE_I = 16;
constexpr std::size_t TILE_J = 16;

struct tuning {
	// A and B are 3D: i x j x k, with k the innermost (contiguous) dimension
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ j_vec ^ i_vec);
} tuning;

// -----------------------------------------------------------------------------
// initialization function
// -----------------------------------------------------------------------------

void init_array(int n, auto A, auto B) {
	// A, B: i x j x k, all dimensions of length n
	using namespace noarr;

	// Precompute 10 / n once to avoid a division in every element initialization.
	const num_t scale = num_t(10.0) / num_t(n);

	traverser(A, B).for_each([&](auto state) {
		auto [i, j, k] = get_indices<'i', 'j', 'k'>(state);

		// Original formula:
		//   A[i][j][k] = B[i][j][k] =
		//     (DATA_TYPE) (i + j + (n - k)) * 10 / n;
		//
		// We evaluate it as:
		//   (i + j + (n - k)) * (10.0 / n)
		// to replace a per-element division with a cheaper multiplication.
		num_t value = num_t(i + j + (n - k)) * scale;

		A[state] = value;
		B[state] = value;
	});
}

// -----------------------------------------------------------------------------
// computation kernel
// -----------------------------------------------------------------------------

[[gnu::flatten, gnu::noinline]]
void kernel_heat_3d(int tsteps, int n, auto A, auto B) {
	// A, B: i x j x k
	using namespace noarr;

	// Precompute constants used in the stencil to reduce per-element work.
	const num_t coeff       = num_t(0.125); // 1/8
	const num_t center_mult = num_t(6.0);   // number of neighbors in 3D 7-point stencil

	// Interior region: i, j, k in [1, n-2]
	// We keep boundaries fixed and only update interior points.
	auto interior =
		noarr::slice<'i'>(1, n - 2) ^
		noarr::slice<'j'>(1, n - 2) ^
		noarr::slice<'k'>(1, n - 2);

	// Spatial blocking in i and j to improve cache locality.
	//
	// We split each dimension into:
	//   - a "body" part that aligns with TILE_* multiples
	//   - a "border" part with the remaining elements
	//
	// into_blocks_static adds an extra tuple-like dimension ('!' / '#')
	// that distinguishes body (index 0) from border (index 1). The traverser
	// automatically handles both; we do not need to treat them explicitly.
	//
	// hoist<'I'> and hoist<'J'> move the block indices to the outer levels
	// of the traversal, so we iterate block-by-block, then elements inside
	// each block, which gives better cache use compared to a pure i-major
	// traversal of the full domain.
	auto tile_i =
		noarr::into_blocks_static<'i', '!', 'I', 'i'>(TILE_I) ^
		noarr::hoist<'I'>();
	auto tile_j =
		noarr::into_blocks_static<'j', '#', 'J', 'j'>(TILE_J) ^
		noarr::hoist<'J'>();

	// Time "dimension" using broadcast: repeats the same spatial domain tsteps times.
	// This keeps the outer time-step loop expressed in terms of a Noarr traverser.
	auto time_bcast = noarr::bcast<'t'>(tsteps);

	// Compose all proto-structures into a single traversal plan:
	//   - time_bcast: logical time dimension
	//   - interior: restrict to interior cells [1, n-2]^3
	//   - tile_i, tile_j: spatial blocking in i and j
	auto trav = traverser(A, B)
		.order(time_bcast ^ interior ^ tile_i ^ tile_j);

	#pragma scop
	trav.template for_dims<'t'>([&](auto t_trav) {
		// t_trav has the current time step 't' fixed.
		// Its for_each will iterate the spatial domain in a tiled order:
		//   blocks in I and J (outer), then i, j, k (inner).
		// The index state passed to the lambda only contains the original
		// spatial dimensions 'i', 'j', 'k' (and not the tiling helper dims).

		// -----------------------------------------------------------------
		// First sweep: update B from A
		// -----------------------------------------------------------------
		t_trav.for_each([&](auto state) {
			using noarr::idx;

			// state contains spatial indices 'i', 'j', 'k'
			const num_t center = A[state];

			// Sum of the six face neighbors around (i, j, k)
			// Using state arithmetic keeps all indexing in terms of named
			// dimensions and lets Noarr compute correct offsets.
			const num_t neighbor_sum =
				A[state + idx<'i'>(1)] + A[state - idx<'i'>(1)] +
				A[state + idx<'j'>(1)] + A[state - idx<'j'>(1)] +
				A[state + idx<'k'>(1)] + A[state - idx<'k'>(1)];

			// Discrete Laplacian: sum(neighbors) - 6*center
			const num_t lap = neighbor_sum - center_mult * center;

			// New value:
			//   center + 0.125 * (sum(neighbors) - 6*center)
			// This is algebraically equivalent to the original code
			// but uses fewer multiplications.
			B[state] = center + coeff * lap;
		});

		// -----------------------------------------------------------------
		// Second sweep: update A from B
		// -----------------------------------------------------------------
		t_trav.for_each([&](auto state) {
			using noarr::idx;

			const num_t center = B[state];

			const num_t neighbor_sum =
				B[state + idx<'i'>(1)] + B[state - idx<'i'>(1)] +
				B[state + idx<'j'>(1)] + B[state - idx<'j'>(1)] +
				B[state + idx<'k'>(1)] + B[state - idx<'k'>(1)];

			const num_t lap = neighbor_sum - center_mult * center;

			A[state] = center + coeff * lap;
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	int n = N;
	int tsteps = TSTEPS;

	// set lengths for spatial dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(n);

	// allocate A and B
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(n, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_heat_3d(tsteps, n, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
