/**
 * Parallel helper:
 * Traverse the *outermost* dimension of `trav` using a range-based for loop,
 * and for each 1D-slab (sub-traverser) run `for_each(body)`.
 *
 * The OpenMP pragma parallelizes over the outer dimension. When OpenMP is
 * disabled, this degrades to a plain serial loop.
 *
 * Requirements:
 *  - `trav` must be a noarr::traverser
 *  - the outermost dimension must be safe to parallelize over
 *    (here it will be 'i', the row index).
 */
template<typename Traverser, typename Body>
inline void parallel_for_each_outer(Traverser &&trav, const Body &body) {
	#pragma omp parallel for schedule(static)
	for (auto subtrav : trav) { // iterates outermost dimension of `trav`
		subtrav.for_each(body); // `body` sees full state (including the fixed index)
	}
}

// initialization function
void init_array(int n, auto A, auto B) {
	// A, B: i x j x k, all dimensions of length n
	using namespace noarr;

	traverser(A, B).for_each([=](auto state) {
		auto [i, j, k] = get_indices<'i', 'j', 'k'>(state);

		// A[i][j][k] = B[i][j][k] =
		//   (DATA_TYPE) (i + j + (n - k)) * 10 / n;
		num_t value = num_t((i + j + (n - k)) * 10) / num_t(n);

		A[state] = value;
		B[state] = value;
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_heat_3d(int tsteps, int n, auto A, auto B) {
	// A, B: i x j x k
	using namespace noarr;

	// Precompute scalar constants once; they are used in every stencil evaluation
	const num_t c_two   = num_t(2.0);
	const num_t c_alpha = num_t(0.125);

	// Interior region: i, j, k in [1, n-2]
	// (indices are relative to original structure, not sliced one)
	auto interior =
		noarr::slice<'i'>(1, n - 2) ^
		noarr::slice<'j'>(1, n - 2) ^
		noarr::slice<'k'>(1, n - 2);

	// Time "dimension" using broadcast: repeats the same spatial domain tsteps times
	auto time_bcast = noarr::bcast<'t'>(tsteps);

	#pragma scop
	traverser(A, B)
		.order(time_bcast)
		// Drive the time-stepping through a synthetic 't' dimension.
		// Each iteration of this for_dims corresponds to one time step.
		.template for_dims<'t'>([&](auto t_trav) {
			// t_trav has 't' fixed; remaining dimensions are 'i', 'j', 'k'.
			// Apply the interior slice; this keeps the domain shape but
			// removes the halo (boundary cells are left untouched).
			auto inner = t_trav.order(interior);

			// First sweep: update B from A on the interior.
			// We keep the arithmetic expression structure identical to the
			// original kernel, but factor out the reusable "2 * center".
			auto sweep_A_to_B = [&](auto state) {
				using noarr::idx;

				const num_t center      = A[state];
				const num_t two_center  = c_two * center;

				const num_t lap_i =
					A[state + idx<'i'>(1)] - two_center + A[state - idx<'i'>(1)];
				const num_t lap_j =
					A[state + idx<'j'>(1)] - two_center + A[state - idx<'j'>(1)];
				const num_t lap_k =
					A[state + idx<'k'>(1)] - two_center + A[state - idx<'k'>(1)];

				B[state] = c_alpha * lap_i
				         + c_alpha * lap_j
				         + c_alpha * lap_k
				         + center;
			};

			// Second sweep: update A from B on the interior.
			auto sweep_B_to_A = [&](auto state) {
				using noarr::idx;

				const num_t center      = B[state];
				const num_t two_center  = c_two * center;

				const num_t lap_i =
					B[state + idx<'i'>(1)] - two_center + B[state - idx<'i'>(1)];
				const num_t lap_j =
					B[state + idx<'j'>(1)] - two_center + B[state - idx<'j'>(1)];
				const num_t lap_k =
					B[state + idx<'k'>(1)] - two_center + B[state - idx<'k'>(1)];

				A[state] = c_alpha * lap_i
				         + c_alpha * lap_j
				         + c_alpha * lap_k
				         + center;
			};

			// Spatial sweeps over the interior; we parallelise over the
			// outermost dimension of `inner`, which is 'i' (rows).
			// Each thread owns a distinct i-slab; all stencil reads are from
			// A/B only, and each cell is written exactly once, so there are
			// no write–write races.
			parallel_for_each_outer(inner, sweep_A_to_B);
			parallel_for_each_outer(inner, sweep_B_to_A);
		});
	#pragma endscop
