[[gnu::flatten, gnu::noinline]]
void kernel_heat_3d(int tsteps, int n, auto A, auto B) {
	// A, B: i x j x k
	using namespace noarr;

	// ---------------------------------------------------------------------
	// Spatial traversal setup
	// ---------------------------------------------------------------------
	// Interior region: i, j, k in [1, n-2]
	// We keep the same spatial domain as in the original code to ensure
	// identical boundary behaviour.
	auto interior =
		noarr::slice<'i'>(1, n - 2) ^
		noarr::slice<'j'>(1, n - 2) ^
		noarr::slice<'k'>(1, n - 2);

	// Base traverser that only iterates over the interior points of A/B.
	// This is reused for every time step; it describes the 3D loop nest
	// over i, j, k. The layout is i (outer), j (middle), k (innermost),
	// with k contiguous in memory.
	auto interior_trav = traverser(A, B).order(interior);

	// Precompute stencil coefficients once; they are the same for all
	// iterations and all time steps.
	const num_t coeff = num_t(0.125); // scaling of the discrete Laplacian
	const num_t two   = num_t(2.0);   // used in -2 * center

	// Pre-create unit index states for neighbour accesses to avoid
	// reconstructing them repeatedly inside the innermost loops.
	const auto di = noarr::idx<'i'>(1);
	const auto dj = noarr::idx<'j'>(1);
	const auto dk = noarr::idx<'k'>(1);

	// ---------------------------------------------------------------------
	// Time-stepping loop
	//
	// The original implementation used a broadcast "time" dimension 't'
	// via noarr::bcast and traverser::for_dims<'t'>. Semantically that
	// simply repeated the same spatial traversal tsteps times while
	// ignoring 't' in the array indexing.
	//
	// Here we implement the same computation with an explicit time loop
	// around a Noarr-based spatial traversal. This preserves the original
	// algorithm while slightly reducing traverser overhead.
	//
	// For each time step:
	//   1) update B from A on the interior region
	//   2) update A from B on the interior region
	//
	// We additionally parallelise the outermost spatial dimension using
	// OpenMP and traverser iterators. When compiled without OpenMP
	// support, the pragmas are ignored and the code remains correct.
	// ---------------------------------------------------------------------

	#pragma scop
	for (int t = 0; t < tsteps; ++t) {
		// -----------------------------------------------------------------
		// First sweep: B <- stencil(A)
		// -----------------------------------------------------------------
		//
		// We parallelise over the topmost traverser dimension (here 'i'),
		// so each thread gets a band of i-slices and iterates the inner
		// j/k loops serially. This gives good cache locality and vector
		// friendliness (k is innermost and contiguous).
		//
		#pragma omp parallel for
		for (auto sub_trav : interior_trav) {
			// sub_trav has 'i' fixed; remaining dimensions are 'j' and 'k'.
			sub_trav.for_each([&](auto state) {
				// state contains 'i', 'j', 'k'
				num_t center = A[state];
				const num_t two_center = two * center;

				// Directional Laplacians along each axis.
				// We reuse two_center to avoid two extra multiplications per
				// direction. The algebraic form is identical to the original:
				//   A[i+1] - 2*center + A[i-1], etc.
				num_t lap_i =
					A[state + di] - two_center + A[state - di];
				num_t lap_j =
					A[state + dj] - two_center + A[state - dj];
				num_t lap_k =
					A[state + dk] - two_center + A[state - dk];

				// Combine directions: original code computed
				//   B = 0.125*lap_i + 0.125*lap_j + 0.125*lap_k + center;
				// We factor the common coefficient:
				//   B = center + 0.125 * (lap_i + lap_j + lap_k);
				// These are mathematically equivalent; the FP evaluation order
				// changes slightly but the algorithm is the same.
				const num_t lap = lap_i + lap_j + lap_k;
				B[state] = center + coeff * lap;
			});
		}

		// -----------------------------------------------------------------
		// Second sweep: A <- stencil(B)
		// -----------------------------------------------------------------
		//
		// Identical stencil, just swapping the roles of A and B.
		//
		#pragma omp parallel for
		for (auto sub_trav : interior_trav) {
			sub_trav.for_each([&](auto state) {
				num_t center = B[state];
				const num_t two_center = two * center;

				num_t lap_i =
					B[state + di] - two_center + B[state - di];
				num_t lap_j =
					B[state + dj] - two_center + B[state - dj];
				num_t lap_k =
					B[state + dk] - two_center + B[state - dk];

				const num_t lap = lap_i + lap_j + lap_k;
				A[state] = center + coeff * lap;
			});
		}
	}
	#pragma endscop
}

