[[gnu::flatten, gnu::noinline]]
void kernel_heat_3d(int tsteps, int n, auto A, auto B) {
	using namespace noarr;

	// Precompute scalar constants once per kernel call.
	// These are used in the stencil update and are captured by reference
	// inside the inner lambdas (they are read-only).
	const num_t weight = num_t(0.125);
	const num_t two    = num_t(2.0);

	// Interior region: i, j, k in [1, n-2]
	// We express this as proto-structure using slices and apply it via
	// traverser.order(interior). States produced by the traverser remain
	// in the original coordinate system (indices 1..n-2), so neighbor
	// arithmetic with ±1 remains valid and never leaves the domain.
	auto interior =
		noarr::slice<'i'>(1, n - 2) ^
		noarr::slice<'j'>(1, n - 2) ^
		noarr::slice<'k'>(1, n - 2);

	// Time "dimension" using broadcast:
	//   repeats the same spatial domain tsteps times.
	// We keep the time-loop expressible via Noarr traverser semantics by
	// adding a broadcast dimension 't' instead of using a plain for-loop.
	auto time_bcast = noarr::bcast<'t'>(tsteps);

	#pragma scop
	traverser(A, B)
		.order(time_bcast)
		// Split traversal in the (logical) time dimension 't'
		.template for_dims<'t'>([&](auto t_trav) {
			// t_trav has a fixed value of 't'; we ignore 't' when indexing A/B.
			// Apply the interior restriction for the spatial domain.
			auto inner = t_trav.order(interior);

			// -----------------------------------------------------------------
			// First sweep: update B from A (A is read-only in this sweep)
			// -----------------------------------------------------------------
			//
			// We parallelize over the outermost spatial dimension of 'inner'
			// (which, given the chosen layout, is 'i'). For each fixed 'i',
			// the respective sub-traverser visits all (j, k) in that plane.
			// This guarantees threads write to disjoint regions of B and
			// only read from A, so there are no data races.
			omp_trav_for_each(inner, [&](auto state) {
				using noarr::idx;

				const num_t center       = A[state];
				const num_t twice_center = two * center;

				// 1D Laplacians along each axis.
				// We reuse twice_center instead of computing 2*center three
				// times; this saves multiplications without changing the
			// evaluation order of additions/subtractions.
				const num_t lap_i =
					A[state + idx<'i'>(1)] - twice_center + A[state - idx<'i'>(1)];
				const num_t lap_j =
					A[state + idx<'j'>(1)] - twice_center + A[state - idx<'j'>(1)];
				const num_t lap_k =
					A[state + idx<'k'>(1)] - twice_center + A[state - idx<'k'>(1)];

				B[state] = weight * lap_i
				         + weight * lap_j
				         + weight * lap_k
				         + center;
			});

			// -----------------------------------------------------------------
			// Second sweep: update A from B (B is read-only in this sweep)
			// -----------------------------------------------------------------
			//
			// We must finish the first sweep (all updates to B) before we
			// start reading B here. omp_trav_for_each enforces a barrier at
			// the end of its parallel region, so the second sweep sees a
			// fully updated B for the given time index 't'.
			omp_trav_for_each(inner, [&](auto state) {
				using noarr::idx;

				const num_t center       = B[state];
				const num_t twice_center = two * center;

				const num_t lap_i =
					B[state + idx<'i'>(1)] - twice_center + B[state - idx<'i'>(1)];
				const num_t lap_j =
					B[state + idx<'j'>(1)] - twice_center + B[state - idx<'j'>(1)];
				const num_t lap_k =
					B[state + idx<'k'>(1)] - twice_center + B[state - idx<'k'>(1)];

				A[state] = weight * lap_i
				         + weight * lap_j
				         + weight * lap_k
				         + center;
			});
		});
	#pragma endscop
}

