// -----------------------------------------------------------------------------
// Small helper: parallelize traversal over the *outermost* dimension using OpenMP
// Each iteration of the parallel loop gets a sub-traverser with that
// outermost dimension fixed and then walks the remaining dimensions serially.
// If the code is compiled without OpenMP, the pragma is ignored and this
// becomes a plain serial loop.
// -----------------------------------------------------------------------------
template<typename Traverser, typename Func>
inline void parallel_for_each_outer(Traverser trav, const Func &func) {
	// trav has some outermost dimension (here: 'i'); the iterator provided
	// by traverser_iter.hpp gives us a sub-traverser with that dimension fixed.
	#pragma omp parallel for schedule(static)
	for (auto sub_trav : trav) {
		sub_trav.for_each(func);
	}
}

