// 7-point 3D stencil, two sweeps per time step: B <- A, then A <- B
[[gnu::flatten, gnu::noinline]]
void kernel_heat_3d(int tsteps, int n, auto A, auto B) {
	using namespace noarr;

	// --- Spatial region and traversal setup ----------------------------------

	// Interior region: i, j, k in [1, n-2]
	// Boundary values (Dirichlet) remain unchanged over time.
	auto interior =
		noarr::slice<'i'>(1, n - 2) ^
		noarr::slice<'j'>(1, n - 2) ^
		noarr::slice<'k'>(1, n - 2);

	// Spatial traverser over A and B restricted to the interior.
	// Dimensions: 'i' (outer), 'j', 'k' (inner, contiguous in memory).
	auto space_trav = traverser(A, B).order(interior);

	// Precompute index increments for the 6 neighbors (compile-time objects).
	const auto di = noarr::idx<'i'>(1);
	const auto dj = noarr::idx<'j'>(1);
	const auto dk = noarr::idx<'k'>(1);

	// Coefficients for the update:
	//   lap = sum(neighbors) - 6*center
	//   new = center + 0.125 * lap
	//       = 0.25 * center + 0.125 * sum(neighbors)
	constexpr num_t coeff_nb     = num_t(0.125); // weight of each neighbor sum
	constexpr num_t coeff_center = num_t(0.25);  // effective center coefficient

	// Lambda for a single sweep: B <- stencil(A)
	const auto sweep_A_to_B = [&](auto state) {
		const num_t center = A[state];

		// 6 neighbors
		const num_t xp = A[state + di];
		const num_t xm = A[state - di];
		const num_t yp = A[state + dj];
		const num_t ym = A[state - dj];
		const num_t zp = A[state + dk];
		const num_t zm = A[state - dk];

		const num_t neighbor_sum = xp + xm + yp + ym + zp + zm;

		// Fused stencil formula (fewer multiplications than original form)
		B[state] = coeff_center * center + coeff_nb * neighbor_sum;
	};

	// Lambda for a single sweep: A <- stencil(B)
	const auto sweep_B_to_A = [&](auto state) {
		const num_t center = B[state];

		const num_t xp = B[state + di];
		const num_t xm = B[state - di];
		const num_t yp = B[state + dj];
		const num_t ym = B[state - dj];
		const num_t zp = B[state + dk];
		const num_t zm = B[state - dk];

		const num_t neighbor_sum = xp + xm + yp + ym + zp + zm;

		A[state] = coeff_center * center + coeff_nb * neighbor_sum;
	};

	#pragma scop
	// Time loop: each iteration performs two stencil sweeps:
	//   1) B = stencil(A)
	//   2) A = stencil(B)
	//
	// Spatial loops are expressed via Noarr traversers. The helper
	// parallel_for_each_outer uses OpenMP to split the outer 'i'
	// dimension among threads; inner 'j'/'k' loops remain serial and
	// keep 'k' as the innermost, contiguous dimension for good locality.
	for (int t = 0; t < tsteps; ++t) {
		// First sweep: update B from A
		parallel_for_each_outer(space_trav, sweep_A_to_B);

		// Second sweep: update A from B
		parallel_for_each_outer(space_trav, sweep_B_to_A);
	}
	#pragma endscop
}

